public:
    int findShortestSubArray(vector<int>& nums) {

        map<int, vector<int>>m;
        int n=nums.size();
        int maxOccur=0;

        for(int i=0; i<n; i++){
            m[nums[i]].push_back(i);
            if(m[nums[i]].size()>maxOccur)
                maxOccur=m[nums[i]].size();
        }

        int minSubArray=INT_MAX;

        for(auto look:m){
            if(look.second.size()==maxOccur){
                int firstOccur=look.second[0];
                int lastOccur=look.second[maxOccur-1];
                minSubArray=min(minSubArray,lastOccur-firstOccur+1);
            }  
        }

        return minSubArray;
    }
};

class Solution(object):
    def findShortestSubArray(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        d = {}
        for i, num in enumerate(nums):
            if num in d:
                d[num][0] += 1
                d[num][2] = i
            else:
                d[num] = [1, i, i]
        ans = float("inf")
        max_freq = 0
        for freq, l, r in d.values():
            if freq > max_freq:
                max_freq = freq
                ans = r - l + 1
            elif freq == max_freq:
                ans = min(ans, r - l + 1)
        return ans
